package outbox

import (
	"context"

	"github.com/Sokol111/ecommerce-commons/pkg/kafka/producer"
	"github.com/twmb/franz-go/pkg/kgo"
	"go.uber.org/zap"
)

type Sender struct {
	producer        producer.Producer
	entitiesChan    <-chan *OutboxEntity
	confirmChan     chan<- ConfirmResult
	logger          *zap.Logger
	tracePropagator TracePropagator
}

func NewSender(
	producer producer.Producer,
	entitiesChan chan *OutboxEntity,
	confirmChan chan ConfirmResult,
	logger *zap.Logger,
	tracePropagator TracePropagator,
) *Sender {
	return &Sender{
		producer:        producer,
		entitiesChan:    entitiesChan,
		confirmChan:     confirmChan,
		logger:          logger,
		tracePropagator: tracePropagator,
	}
}

func (s *Sender) Run(ctx context.Context) error {
	defer s.logger.Info("sender worker stopped")

	for {
		select {
		case <-ctx.Done():
			return nil
		default:
		}

		select {
		case <-ctx.Done():
			return nil
		case entity := <-s.entitiesChan:
			s.send(ctx, entity)
			s.logger.Debug("outbox sent to kafka", zap.String("id", entity.ID))
		}
	}
}

func (s *Sender) send(ctx context.Context, entity *OutboxEntity) {
	_, span, kafkaHeaders := s.tracePropagator.StartKafkaProducerSpan(entity.Headers, entity.Topic, entity.ID)
	defer span.End()

	record := &kgo.Record{
		Topic:   entity.Topic,
		Key:     []byte(entity.Key),
		Value:   entity.Payload,
		Headers: kafkaHeaders,
	}

	entityID := entity.ID
	confirmChan := s.confirmChan
	s.producer.Produce(ctx, record, func(_ *kgo.Record, err error) {
		confirmChan <- ConfirmResult{ID: entityID, Err: err}
	})
}

package fxconfig

import (
	fx_kafka_config "github.com/Sokol111/ecommerce-commons/pkg/kafka/config/fxconfig"
	fx_kafkaproto "github.com/Sokol111/ecommerce-commons/pkg/kafka/kafkaproto/fxconfig"
	fx_outbox "github.com/Sokol111/ecommerce-commons/pkg/kafka/outbox/fxconfig"
	fx_producer "github.com/Sokol111/ecommerce-commons/pkg/kafka/producer/fxconfig"
	"go.uber.org/fx"
)

// NewKafkaModule provides kafka functionality: outbox, consumer, producer.
func NewKafkaModule() fx.Option {
	return fx.Options(
		fx_kafka_config.NewKafkaConfigModule(),
		fx_producer.NewProducerModule(),
		fx_kafkaproto.NewProtoModule(),
		fx_outbox.NewOutboxModule(),
	)
}

package fxconfig

import (
	"context"
	"strings"
	"time"

	"github.com/Sokol111/ecommerce-commons/pkg/core/health"
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/config"
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/producer"
	"github.com/twmb/franz-go/pkg/kadm"
	"github.com/twmb/franz-go/pkg/kgo"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

// NewProducerModule provides Kafka producer components for dependency injection.
func NewProducerModule() fx.Option {
	return fx.Options(
		fx.Provide(
			provideKgoClient,
			provideProducer,
		),
		fx.Invoke(invokeInitializer),
	)
}

func provideKgoClient(lc fx.Lifecycle, conf config.Config) (*kgo.Client, error) {
	brokers := strings.Split(conf.Brokers, ",")

	compression := compressionCodec(conf.ProducerConfig.Compression)

	client, err := kgo.NewClient(
		kgo.SeedBrokers(brokers...),
		kgo.AllowAutoTopicCreation(),
		kgo.ProducerLinger(conf.ProducerConfig.Linger),
		kgo.ProducerBatchCompression(compression),
		kgo.RecordDeliveryTimeout(conf.ProducerConfig.DeliveryTimeout),
		kgo.MaxBufferedRecords(conf.ProducerConfig.MaxBufferedRecords),
	)
	if err != nil {
		return nil, err
	}

	lc.Append(fx.Hook{
		OnStop: func(ctx context.Context) error {
			client.Close()
			return nil
		},
	})

	return client, nil
}

func invokeInitializer(lc fx.Lifecycle, readiness health.ComponentManager, client *kgo.Client, log *zap.Logger, conf config.Config) {
	markReady := readiness.AddComponent("kafka-producer")
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			if err := waitForBrokers(ctx, client, log.With(zap.String("component", "producer")), conf.ProducerConfig.ReadinessTimeoutSeconds, conf.ProducerConfig.FailOnBrokerError); err != nil {
				return err
			}
			markReady()
			return nil
		},
	})
}

func provideProducer(client *kgo.Client) producer.Producer {
	return client
}

func compressionCodec(name string) kgo.CompressionCodec {
	switch name {
	case "snappy":
		return kgo.SnappyCompression()
	case "lz4":
		return kgo.Lz4Compression()
	case "zstd":
		return kgo.ZstdCompression()
	case "none":
		return kgo.NoCompression()
	default:
		return kgo.NoCompression()
	}
}

func waitForBrokers(ctx context.Context, client *kgo.Client, log *zap.Logger, timeoutSec int, failOnError bool) error {
	log.Info("waiting for kafka brokers", zap.Int("timeout_seconds", timeoutSec))

	if timeoutSec > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(timeoutSec)*time.Second)
		defer cancel()
	}

	if err := pollBrokers(ctx, client); err != nil {
		if failOnError {
			return err
		}
		log.Warn("brokers not ready, continuing", zap.Error(err))
	}

	log.Info("producer ready")
	return nil
}

func pollBrokers(ctx context.Context, client *kgo.Client) error {
	admClient := kadm.NewClient(client)
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}

		brokers, err := admClient.ListBrokers(ctx)
		if err == nil && len(brokers) > 0 {
			return nil
		}

		time.Sleep(500 * time.Millisecond)
	}
}

package fxconfig

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Sokol111/ecommerce-commons/pkg/core/health"
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/config"
	"github.com/twmb/franz-go/pkg/kadm"
	"github.com/twmb/franz-go/pkg/kgo"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

func provideConsumerClient(lc fx.Lifecycle, conf config.Config, consumerConf config.ConsumerConfig, log *zap.Logger, componentMgr health.ComponentManager) (*kgo.Client, error) {
	brokers := strings.Split(conf.Brokers, ",")

	resetOffset := kgo.NewOffset().AtEnd()
	if consumerConf.AutoOffsetReset == "earliest" {
		resetOffset = kgo.NewOffset().AtStart()
	}

	opts := []kgo.Opt{
		kgo.SeedBrokers(brokers...),
		kgo.ConsumerGroup(consumerConf.GroupID),
		kgo.ConsumeTopics(consumerConf.Topic),
		kgo.ConsumeResetOffset(resetOffset),
		kgo.AutoCommitInterval(3 * time.Second),
		kgo.AutoCommitMarks(),
		kgo.OnPartitionsAssigned(func(ctx context.Context, cl *kgo.Client, assigned map[string][]int32) {
			for topic, parts := range assigned {
				log.Info("partitions assigned",
					zap.String("topic", topic),
					zap.Int("partition_count", len(parts)),
					zap.Int32s("partitions", parts))
			}
		}),
		kgo.OnPartitionsRevoked(func(ctx context.Context, cl *kgo.Client, revoked map[string][]int32) {
			for topic, parts := range revoked {
				log.Info("partitions revoked",
					zap.String("topic", topic),
					zap.Int("partition_count", len(parts)),
					zap.Int32s("partitions", parts))
			}
		}),
		kgo.OnPartitionsLost(func(ctx context.Context, cl *kgo.Client, lost map[string][]int32) {
			for topic, parts := range lost {
				log.Warn("partitions lost",
					zap.String("topic", topic),
					zap.Int("partition_count", len(parts)),
					zap.Int32s("partitions", parts))
			}
		}),
	}

	client, err := kgo.NewClient(opts...)
	if err != nil {
		return nil, fmt.Errorf("failed to create kafka consumer, name: %s: %w", consumerConf.Name, err)
	}

	componentName := "kafka-consumer-" + consumerConf.Name
	markReady := componentMgr.AddComponent(componentName)

	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			log.Info("subscribing to topic", zap.String("topic", consumerConf.Topic))

			// Verify topic is available
			if err := verifyTopicAvailable(ctx, client, consumerConf.Topic, log); err != nil {
				if consumerConf.FailOnTopicError {
					return err
				}
				log.Warn("topic verification failed, continuing anyway", zap.Error(err))
			}

			markReady()
			return nil
		},
		OnStop: func(ctx context.Context) error {
			log.Info("closing kafka consumer")
			client.Close()
			return nil
		},
	})

	return client, nil
}

// verifyTopicAvailable checks if topic exists and has partitions.
func verifyTopicAvailable(ctx context.Context, client *kgo.Client, topic string, log *zap.Logger) error {
	admClient := kadm.NewClient(client)
	topics, err := admClient.ListTopics(ctx, topic)
	if err != nil {
		return fmt.Errorf("failed to get topic metadata: %w", err)
	}

	topicDetail, ok := topics[topic]
	if !ok {
		return fmt.Errorf("topic %s not found in metadata", topic)
	}

	if topicDetail.Err != nil {
		return fmt.Errorf("topic %s has error: %w", topic, topicDetail.Err)
	}

	if len(topicDetail.Partitions) == 0 {
		return fmt.Errorf("topic %s has no partitions", topic)
	}

	log.Info("topic is ready",
		zap.String("topic", topic),
		zap.Int("partitions", len(topicDetail.Partitions)))
	return nil
}

